import * as React from 'react';
import {
  PageSection,
  Title,
  Content,
  Card,
  CardTitle,
  CardBody,
  Form,
  FormGroup,
  Radio,
  TextInput,
  Button,
  ActionGroup,
  Stack,
  StackItem,
  Popover,
  Flex,
  FlexItem,
} from '@patternfly/react-core';
import HelpIcon from '@patternfly/react-icons/dist/esm/icons/help-icon';

type HookOption = 'none' | 'manual' | 'aap';

const AAP_CONNECTED_VALUE = 'https://aap.redhat.com (configured)';

const ConfigureMigrationHooks: React.FunctionComponent = () => {
  const [preHook, setPreHook] = React.useState<HookOption>('aap');
  const [postHook, setPostHook] = React.useState<HookOption>('none');
  const [aapToken, setAapToken] = React.useState('');
  const [preHookRunnerImage, setPreHookRunnerImage] = React.useState('');
  const [preServiceAccount, setPreServiceAccount] = React.useState('');
  const [postHookRunnerImage, setPostHookRunnerImage] = React.useState('');
  const [postServiceAccount, setPostServiceAccount] = React.useState('');

  const onPreHookChange = (_event: React.FormEvent<HTMLInputElement>, checked: boolean) => {
    if (checked) {
      setPreHook(_event.currentTarget.value as HookOption);
    }
  };

  const onPostHookChange = (_event: React.FormEvent<HTMLInputElement>, checked: boolean) => {
    if (checked) {
      setPostHook(_event.currentTarget.value as HookOption);
    }
  };

  return (
    <>
      <PageSection variant="default">
        <Stack hasGutter>
          <StackItem>
            <Title headingLevel="h1" size="2xl" className="pf-v6-u-mb-sm">
              Configure Migration Hooks
            </Title>
            <Content className="pf-v6-u-color-200 pf-v6-u-max-width-2xl">
              Hooks allow you to run Ansible playbooks before or after migration.
            </Content>
          </StackItem>

          <StackItem>
            <Card>
              <CardTitle>Pre-Migration Hook</CardTitle>
              <CardBody>
                <Form>
                  <FormGroup role="radiogroup" fieldId="pre-hook-options" label="" hasNoPaddingTop>
                    <Stack hasGutter>
                      <StackItem>
                        <Radio
                          id="pre-none"
                          name="pre-hook"
                          value="none"
                          label="No hook"
                          isChecked={preHook === 'none'}
                          onChange={onPreHookChange}
                        />
                      </StackItem>
                      <StackItem>
                        <Radio
                          id="pre-manual"
                          name="pre-hook"
                          value="manual"
                          label="Manual entry (paste base64-encoded playbook)"
                          isChecked={preHook === 'manual'}
                          onChange={onPreHookChange}
                        />
                        {preHook === 'manual' && (
                          <Stack hasGutter className="pf-v6-u-ml-lg pf-v6-u-mt-md">
                            <StackItem>
                              <FormGroup label="Hook runner image" fieldId="pre-hook-runner-image">
                                <TextInput
                                  id="pre-hook-runner-image"
                                  value={preHookRunnerImage}
                                  onChange={(_event, value) => setPreHookRunnerImage(value)}
                                  placeholder="Enter hook runner image"
                                  aria-label="Pre-migration hook runner image"
                                />
                              </FormGroup>
                            </StackItem>
                            <StackItem>
                              <FormGroup label="Service account" fieldId="pre-service-account">
                                <TextInput
                                  id="pre-service-account"
                                  value={preServiceAccount}
                                  onChange={(_event, value) => setPreServiceAccount(value)}
                                  placeholder="Enter service account"
                                  aria-label="Pre-migration service account"
                                />
                              </FormGroup>
                            </StackItem>
                          </Stack>
                        )}
                      </StackItem>
                      <StackItem>
                        <Radio
                          id="pre-aap"
                          name="pre-hook"
                          value="aap"
                          label="Retrieve from Ansible Automation Platform"
                          isChecked={preHook === 'aap'}
                          onChange={onPreHookChange}
                        />
                        {preHook === 'aap' && (
                          <Stack hasGutter className="pf-v6-u-ml-lg pf-v6-u-mt-md">
                            <StackItem>
                              <FormGroup label="Connected" fieldId="pre-aap-connected">
                                <TextInput
                                  id="pre-aap-connected"
                                  value={AAP_CONNECTED_VALUE}
                                  readOnly
                                  aria-label="AAP connection status"
                                />
                              </FormGroup>
                            </StackItem>
                            <StackItem>
                              <FormGroup
                                className="configure-migration-hooks__aap-token-field"
                                label={
                                  <Flex alignItems={{ default: 'alignItemsCenter' }} gap={{ default: 'gapSm' }}>
                                    <FlexItem>AAP token</FlexItem>
                                    <FlexItem>
                                      <Popover
                                        bodyContent={
                                          <div>
                                            Enter the token from your Ansible Automation Platform
                                            instance. This is used to authenticate and retrieve
                                            playbooks.
                                          </div>
                                        }
                                        position="right"
                                        enableFlip
                                        aria-label="AAP token help"
                                        closeBtnAriaLabel="Close help"
                                      >
                                        <Button
                                          variant="plain"
                                          aria-label="AAP token help"
                                          icon={<HelpIcon />}
                                        />
                                      </Popover>
                                    </FlexItem>
                                  </Flex>
                                }
                                fieldId="pre-aap-token"
                              >
                                <TextInput
                                  id="pre-aap-token"
                                  type="password"
                                  value={aapToken}
                                  onChange={(_event, value) => setAapToken(value)}
                                  placeholder="Enter your AAP token"
                                  aria-label="AAP token"
                                />
                              </FormGroup>
                            </StackItem>
                          </Stack>
                        )}
                      </StackItem>
                    </Stack>
                  </FormGroup>
                </Form>
              </CardBody>
            </Card>
          </StackItem>

          <StackItem>
            <Card>
              <CardTitle>Post-Migration Hook</CardTitle>
              <CardBody>
                <Form>
                  <FormGroup role="radiogroup" fieldId="post-hook-options" label="" hasNoPaddingTop>
                    <Stack hasGutter>
                      <StackItem>
                        <Radio
                          id="post-none"
                          name="post-hook"
                          value="none"
                          label="No hook"
                          isChecked={postHook === 'none'}
                          onChange={onPostHookChange}
                        />
                      </StackItem>
                      <StackItem>
                        <Radio
                          id="post-manual"
                          name="post-hook"
                          value="manual"
                          label="Manual entry (paste base64-encoded playbook)"
                          isChecked={postHook === 'manual'}
                          onChange={onPostHookChange}
                        />
                        {postHook === 'manual' && (
                          <Stack hasGutter className="pf-v6-u-ml-lg pf-v6-u-mt-md">
                            <StackItem>
                              <FormGroup label="Hook runner image" fieldId="post-hook-runner-image">
                                <TextInput
                                  id="post-hook-runner-image"
                                  value={postHookRunnerImage}
                                  onChange={(_event, value) => setPostHookRunnerImage(value)}
                                  placeholder="Enter hook runner image"
                                  aria-label="Post-migration hook runner image"
                                />
                              </FormGroup>
                            </StackItem>
                            <StackItem>
                              <FormGroup label="Service account" fieldId="post-service-account">
                                <TextInput
                                  id="post-service-account"
                                  value={postServiceAccount}
                                  onChange={(_event, value) => setPostServiceAccount(value)}
                                  placeholder="Enter service account"
                                  aria-label="Post-migration service account"
                                />
                              </FormGroup>
                            </StackItem>
                          </Stack>
                        )}
                      </StackItem>
                      <StackItem>
                        <Radio
                          id="post-aap"
                          name="post-hook"
                          value="aap"
                          label="Retrieve from Ansible Automation Platform"
                          isChecked={postHook === 'aap'}
                          onChange={onPostHookChange}
                        />
                        {postHook === 'aap' && (
                          <Stack hasGutter className="pf-v6-u-ml-lg pf-v6-u-mt-md">
                            <StackItem>
                              <FormGroup label="Connected" fieldId="post-aap-connected">
                                <TextInput
                                  id="post-aap-connected"
                                  value={AAP_CONNECTED_VALUE}
                                  readOnly
                                  aria-label="AAP connection status"
                                />
                              </FormGroup>
                            </StackItem>
                            <StackItem>
                              <FormGroup
                                className="configure-migration-hooks__aap-token-field"
                                label={
                                  <Flex alignItems={{ default: 'alignItemsCenter' }} gap={{ default: 'gapSm' }}>
                                    <FlexItem>AAP token</FlexItem>
                                    <FlexItem>
                                      <Popover
                                        bodyContent={
                                          <div>
                                            Enter the token from your Ansible Automation Platform
                                            instance. This is used to authenticate and retrieve
                                            playbooks.
                                          </div>
                                        }
                                        position="right"
                                        enableFlip
                                        aria-label="AAP token help"
                                        closeBtnAriaLabel="Close help"
                                      >
                                        <Button
                                          variant="plain"
                                          aria-label="AAP token help"
                                          icon={<HelpIcon />}
                                        />
                                      </Popover>
                                    </FlexItem>
                                  </Flex>
                                }
                                fieldId="post-aap-token"
                              >
                                <TextInput
                                  id="post-aap-token"
                                  type="password"
                                  value={aapToken}
                                  onChange={(_event, value) => setAapToken(value)}
                                  placeholder="Enter your AAP token"
                                  aria-label="AAP token"
                                />
                              </FormGroup>
                            </StackItem>
                          </Stack>
                        )}
                      </StackItem>
                    </Stack>
                  </FormGroup>
                </Form>
              </CardBody>
            </Card>
          </StackItem>

          <StackItem className="pf-v6-u-pt-lg">
            <ActionGroup>
              <Button variant="secondary">Back</Button>
              <Button variant="primary">Next</Button>
            </ActionGroup>
          </StackItem>
        </Stack>
      </PageSection>
    </>
  );
};

export { ConfigureMigrationHooks };
