import * as React from 'react';
import {
  PageSection,
  Title,
  Card,
  CardTitle,
  CardBody,
  FormGroup,
  Checkbox,
  TextInput,
  Stack,
  Flex,
  FlexItem,
  Label,
  LabelGroup,
  TreeView,
  TreeViewDataItem,
  Tabs,
  Tab,
  TabTitleText,
  Wizard,
  WizardStep,
  Button,
  Content,
  ExpandableSection,
} from '@patternfly/react-core';
import { useWizardContext } from '@patternfly/react-core';

type DestinationId = 'cloudwatch' | 's3';

interface Group {
  id: string;
  name: string;
}

interface Application {
  id: string;
  name: string;
  groupId: string;
}

const MOCK_GROUPS: Group[] = [
  { id: 'g1', name: 'API' },
  { id: 'g2', name: 'Scheduler' },
  { id: 'g3', name: 'Authentication' },
  { id: 'g4', name: 'Not applicable' },
];

const MOCK_APPLICATIONS: Application[] = [
  { id: 'a1', name: 'audit-webhook', groupId: 'g1' },
  { id: 'a2', name: 'kube-apiserver', groupId: 'g1' },
  { id: 'a3', name: 'oauth-openshift', groupId: 'g1' },
  { id: 'a4', name: 'openshift-apiserver', groupId: 'g1' },
  { id: 'a5', name: 'openshift-oauth-apiserver', groupId: 'g1' },
  { id: 'a6', name: 'packageserver', groupId: 'g1' },
  { id: 'a7', name: 'validation-webhook', groupId: 'g1' },
  { id: 'a8', name: 'ignition-server', groupId: 'g3' },
  { id: 'a9', name: 'konnectivity-agent', groupId: 'g3' },
];

function getGroupById(id: string): Group | undefined {
  return MOCK_GROUPS.find((g) => g.id === id);
}

function getAppIdsUnderNode(item: TreeViewDataItem): string[] {
  const group = MOCK_GROUPS.find((g) => g.id === item.id);
  if (group) return MOCK_APPLICATIONS.filter((a) => a.groupId === group.id).map((a) => a.id);
  if (item.id && MOCK_APPLICATIONS.some((a) => a.id === item.id)) return [item.id];
  return [];
}

function buildTreeData(selectedAppIds: string[]): TreeViewDataItem[] {
  const selected = new Set(selectedAppIds);
  return MOCK_GROUPS.map((group) => {
    const appsInGroup = MOCK_APPLICATIONS.filter((a) => a.groupId === group.id);
    const children: TreeViewDataItem[] = appsInGroup.map((app) => ({
      id: app.id,
      name: app.name,
      checkProps: { checked: selected.has(app.id) },
    }));
    const allChecked = appsInGroup.length > 0 && appsInGroup.every((a) => selected.has(a.id));
    const someChecked = appsInGroup.some((a) => selected.has(a.id));
    const groupChecked: boolean | null = allChecked ? true : someChecked ? null : false;
    return {
      id: group.id,
      name: group.name,
      defaultExpanded: false,
      children,
      checkProps: { checked: groupChecked },
    };
  });
}

export const DESTINATION_LABELS: Record<DestinationId, string> = {
  cloudwatch: 'CloudWatch',
  s3: 'S3 Bucket',
};

/** Config shape for log forwarding (read-only view / edit save) */
export interface LogForwardingConfig {
  enabledDestinations: DestinationId[];
  selectedApps: Record<DestinationId, string[]>;
  cloudwatchRoleArn: string;
  cloudwatchLogGroupName: string;
  s3BucketName: string;
  s3BucketPrefix: string;
}

const defaultLogForwardingConfig: LogForwardingConfig = {
  enabledDestinations: [],
  selectedApps: { cloudwatch: [], s3: [] },
  cloudwatchRoleArn: '',
  cloudwatchLogGroupName: '',
  s3BucketName: '',
  s3BucketPrefix: '',
};

/** Resolve application display name for read-only views */
export function getApplicationName(appId: string): string {
  const app = MOCK_APPLICATIONS.find((a) => a.id === appId);
  return app?.name ?? appId;
}

/** Shared props for destination settings (form fields + tree + selected apps) */
interface DestinationSettingsContentProps {
  dest: DestinationId;
  selectedApps: Record<DestinationId, string[]>;
  cloudwatchRoleArn: string;
  setCloudwatchRoleArn: (v: string) => void;
  cloudwatchLogGroupName: string;
  setCloudwatchLogGroupName: (v: string) => void;
  s3BucketName: string;
  setS3BucketName: (v: string) => void;
  s3BucketPrefix: string;
  setS3BucketPrefix: (v: string) => void;
  handleTreeCheck: (dest: DestinationId) => (
    event: React.ChangeEvent<HTMLInputElement>,
    item: TreeViewDataItem,
    parentItem: TreeViewDataItem
  ) => void;
  removeAppFromDestination: (dest: DestinationId, appId: string) => void;
  variant: 'card' | 'flat';
  /** Extra class for content wrapper (e.g. for caret alignment) */
  contentClassName?: string;
}

/** Renders Role ARN/Bucket fields + tree + selected apps for one destination */
const DestinationSettingsContent: React.FunctionComponent<DestinationSettingsContentProps> = ({
  dest,
  selectedApps,
  cloudwatchRoleArn,
  setCloudwatchRoleArn,
  cloudwatchLogGroupName,
  setCloudwatchLogGroupName,
  s3BucketName,
  setS3BucketName,
  s3BucketPrefix,
  setS3BucketPrefix,
  handleTreeCheck,
  removeAppFromDestination,
  variant,
  contentClassName = '',
}) => (
  <Stack hasGutter className={contentClassName} style={{ paddingLeft: 24 }}>
    {dest === 'cloudwatch' && (
      <>
        <FormGroup label="Log group name" fieldId={`cloudwatch-log-group-${dest}`} isRequired>
          <TextInput
            id={`cloudwatch-log-group-${dest}`}
            type="text"
            value={cloudwatchLogGroupName}
            onChange={(_e, value) => setCloudwatchLogGroupName(value ?? '')}
            placeholder="Enter log group name"
            aria-label="Log group name"
          />
        </FormGroup>
        <FormGroup label="Role ARN" fieldId={`cloudwatch-role-arn-${dest}`} isRequired>
          <TextInput
            id={`cloudwatch-role-arn-${dest}`}
            type="text"
            value={cloudwatchRoleArn}
            onChange={(_e, value) => setCloudwatchRoleArn(value ?? '')}
            placeholder="Enter role ARN"
            aria-label="Role ARN"
          />
        </FormGroup>
      </>
    )}
    {dest === 's3' && (
      <>
        <FormGroup label="Bucket name" fieldId={`s3-bucket-name-${dest}`} isRequired>
          <TextInput
            id={`s3-bucket-name-${dest}`}
            type="text"
            value={s3BucketName}
            onChange={(_e, value) => setS3BucketName(value ?? '')}
            placeholder="Enter bucket name"
            aria-label="Bucket name"
          />
        </FormGroup>
        <FormGroup label="Bucket prefix" fieldId={`s3-bucket-prefix-${dest}`}>
          <TextInput
            id={`s3-bucket-prefix-${dest}`}
            type="text"
            value={s3BucketPrefix}
            onChange={(_e, value) => setS3BucketPrefix(value ?? '')}
            placeholder="Enter bucket prefix"
            aria-label="Bucket prefix"
          />
        </FormGroup>
      </>
    )}
    {variant === 'card' ? (
      <Flex direction={{ default: 'column', lg: 'row' }} gap={{ default: 'gapMd', lg: 'gapLg' }}>
        <FlexItem flex={{ default: 'flex_1', lg: 'flex_1' }}>
          <Card>
            <CardBody>
              <FormGroup label="Select groups and/or applications" fieldId={`tree-${dest}`} isRequired>
                <TreeView
                  id={`tree-${dest}`}
                  aria-label={`Groups and applications for ${DESTINATION_LABELS[dest]}`}
                  data={buildTreeData(selectedApps[dest] || [])}
                  hasCheckboxes
                  onCheck={handleTreeCheck(dest)}
                />
              </FormGroup>
            </CardBody>
          </Card>
        </FlexItem>
        <FlexItem flex={{ default: 'flex_1', lg: 'flex_1' }}>
          <Card>
            <CardBody>
              <FormGroup label="Selected applications" fieldId={`chips-${dest}-card`}>
                {(selectedApps[dest]?.length ?? 0) > 0 ? (
                  <Stack hasGutter>
                    {MOCK_GROUPS.map((group) => {
                      const selectedInGroup = (selectedApps[dest] || []).filter(
                        (appId) => MOCK_APPLICATIONS.find((a) => a.id === appId)?.groupId === group.id
                      );
                      if (selectedInGroup.length === 0) return null;
                      return (
                        <LabelGroup key={group.id} categoryName={group.name}>
                          {selectedInGroup.map((appId) => {
                            const app = MOCK_APPLICATIONS.find((a) => a.id === appId);
                            if (!app) return null;
                            return (
                              <Label
                                key={app.id}
                                variant="outline"
                                onClose={() => removeAppFromDestination(dest, app.id)}
                                closeBtnAriaLabel={`Remove ${app.name}`}
                              >
                                {app.name}
                              </Label>
                            );
                          })}
                        </LabelGroup>
                      );
                    })}
                  </Stack>
                ) : (
                  <p className="pf-v6-u-color-200 pf-v6-u-m-0">No applications selected</p>
                )}
              </FormGroup>
            </CardBody>
          </Card>
        </FlexItem>
      </Flex>
    ) : (
      <Flex direction={{ default: 'column', lg: 'row' }} gap={{ default: 'gapMd', lg: 'gapLg' }}>
        <FlexItem flex={{ default: 'flex_1', lg: 'flex_1' }}>
          <Card>
            <CardBody>
              <FormGroup label="Select groups and/or applications" fieldId={`tree-${dest}-flat`} isRequired>
                <TreeView
                  id={`tree-${dest}-flat`}
                  aria-label={`Groups and applications for ${DESTINATION_LABELS[dest]}`}
                  data={buildTreeData(selectedApps[dest] || [])}
                  hasCheckboxes
                  onCheck={handleTreeCheck(dest)}
                />
              </FormGroup>
            </CardBody>
          </Card>
        </FlexItem>
        <FlexItem flex={{ default: 'flex_1', lg: 'flex_1' }}>
          <Card>
            <CardBody>
              <FormGroup label="Selected applications" fieldId={`chips-${dest}-flat`}>
              {(selectedApps[dest]?.length ?? 0) > 0 ? (
                <Stack hasGutter>
                  {MOCK_GROUPS.map((group) => {
                    const selectedInGroup = (selectedApps[dest] || []).filter(
                      (appId) => MOCK_APPLICATIONS.find((a) => a.id === appId)?.groupId === group.id
                    );
                    if (selectedInGroup.length === 0) return null;
                    return (
                      <LabelGroup key={group.id} categoryName={group.name}>
                        {selectedInGroup.map((appId) => {
                          const app = MOCK_APPLICATIONS.find((a) => a.id === appId);
                          if (!app) return null;
                          return (
                            <Label
                              key={app.id}
                              variant="outline"
                              onClose={() => removeAppFromDestination(dest, app.id)}
                              closeBtnAriaLabel={`Remove ${app.name}`}
                            >
                              {app.name}
                            </Label>
                          );
                        })}
                      </LabelGroup>
                    );
                  })}
                </Stack>
              ) : (
                <p className="pf-v6-u-color-200 pf-v6-u-m-0">No applications selected</p>
              )}
              </FormGroup>
            </CardBody>
          </Card>
        </FlexItem>
      </Flex>
    )}
  </Stack>
);

/** Placeholder content for steps that don't have real content yet */
const PlaceholderStepContent: React.FunctionComponent<{ title: string }> = ({ title }) => (
  <Content>
    <p className="pf-v6-u-color-200">{title} configuration will go here.</p>
  </Content>
);

/** Log forwarding step content (cards, tree, chips). Optional controlled mode for cluster details edit. */
interface LogForwardingStepContentProps {
  initialConfig?: LogForwardingConfig;
  onSave?: (config: LogForwardingConfig) => void;
  onCancel?: () => void;
}

const LogForwardingStepContent: React.FunctionComponent<LogForwardingStepContentProps> = ({
  initialConfig,
  onSave,
  onCancel,
}) => {
  const isControlled = initialConfig != null && (onSave != null || onCancel != null);
  const [enabledDestinations, setEnabledDestinations] = React.useState<DestinationId[]>(
    initialConfig?.enabledDestinations ?? []
  );
  const [selectedApps, setSelectedApps] = React.useState<Record<DestinationId, string[]>>(
    initialConfig?.selectedApps ?? { cloudwatch: [], s3: [] }
  );
  const [cloudwatchRoleArn, setCloudwatchRoleArn] = React.useState(initialConfig?.cloudwatchRoleArn ?? '');
  const [cloudwatchLogGroupName, setCloudwatchLogGroupName] = React.useState(
    initialConfig?.cloudwatchLogGroupName ?? ''
  );
  const [s3BucketName, setS3BucketName] = React.useState(initialConfig?.s3BucketName ?? '');
  const [s3BucketPrefix, setS3BucketPrefix] = React.useState(initialConfig?.s3BucketPrefix ?? '');
  const [settingsExpanded, setSettingsExpanded] = React.useState<Record<DestinationId, boolean>>({
    cloudwatch: true,
    s3: true,
  });
  const [activeTabKey, setActiveTabKey] = React.useState<string | number>(0);

  const getCurrentConfig = (): LogForwardingConfig => ({
    enabledDestinations: [...enabledDestinations],
    selectedApps: { cloudwatch: [...(selectedApps.cloudwatch ?? [])], s3: [...(selectedApps.s3 ?? [])] },
    cloudwatchRoleArn,
    cloudwatchLogGroupName,
    s3BucketName,
    s3BucketPrefix,
  });

  const handleTabSelect = (_e: React.SyntheticEvent<HTMLElement>, tabIndex: string | number) => {
    setActiveTabKey(tabIndex);
  };

  const toggleDestination = (id: DestinationId) => {
    setEnabledDestinations((prev) =>
      prev.includes(id) ? prev.filter((d) => d !== id) : [...prev, id]
    );
    if (!enabledDestinations.includes(id)) {
      setSelectedApps((prev) => ({ ...prev, [id]: [] }));
    }
  };

  const removeAppFromDestination = (dest: DestinationId, appId: string) => {
    setSelectedApps((prev) => ({
      ...prev,
      [dest]: (prev[dest] || []).filter((id) => id !== appId),
    }));
  };

  const handleTreeCheck = (dest: DestinationId) => (
    event: React.ChangeEvent<HTMLInputElement>,
    item: TreeViewDataItem,
    _parentItem: TreeViewDataItem
  ) => {
    const checked = event.target.checked;
    const appIds = getAppIdsUnderNode(item);
    setSelectedApps((prev) => {
      const list = prev[dest];
      if (checked) {
        const next = new Set([...list, ...appIds]);
        return { ...prev, [dest]: Array.from(next) };
      }
      const removeSet = new Set(appIds);
      return { ...prev, [dest]: list.filter((id) => !removeSet.has(id)) };
    });
  };

  const sharedSettingsProps = {
    selectedApps,
    cloudwatchRoleArn,
    setCloudwatchRoleArn,
    cloudwatchLogGroupName,
    setCloudwatchLogGroupName,
    s3BucketName,
    setS3BucketName,
    s3BucketPrefix,
    setS3BucketPrefix,
    handleTreeCheck,
    removeAppFromDestination,
  };

  return (
    <Stack hasGutter>
      <p className="pf-v6-u-color-200">
        Enable one or both destinations and select which groups and applications to forward logs to.
      </p>
      <Tabs activeKey={activeTabKey} onSelect={handleTabSelect} aria-label="Log forwarding layout tabs">
        <Tab eventKey={0} title={<TabTitleText>Card layout</TabTitleText>} aria-label="Card layout">
          <Flex direction={{ default: 'column' }} gap={{ default: 'gapMd' }} className="pf-v6-u-mt-md">
            {(['cloudwatch', 's3'] as DestinationId[]).map((dest) => (
              <FlexItem key={dest}>
                <Card style={{ height: '100%' }}>
                  <CardTitle>{DESTINATION_LABELS[dest]}</CardTitle>
                  <CardBody>
                    <Stack hasGutter>
                      <Checkbox
                        id={`enable-card-${dest}`}
                        label={`Enable ${DESTINATION_LABELS[dest]}`}
                        isChecked={enabledDestinations.includes(dest)}
                        onChange={() => toggleDestination(dest)}
                        aria-label={`Enable ${DESTINATION_LABELS[dest]}`}
                      />
                      {enabledDestinations.includes(dest) && (
                        <ExpandableSection
                          toggleText="Settings"
                          isExpanded={settingsExpanded[dest]}
                          onToggle={(_e, expanded) =>
                            setSettingsExpanded((prev) => ({ ...prev, [dest]: expanded }))
                          }
                          className="pf-v6-u-mt-sm"
                        >
                          <DestinationSettingsContent
                            dest={dest}
                            {...sharedSettingsProps}
                            variant="card"
                            contentClassName="pf-v6-u-mt-md"
                          />
                        </ExpandableSection>
                      )}
                    </Stack>
                  </CardBody>
                </Card>
              </FlexItem>
            ))}
          </Flex>
        </Tab>
        <Tab eventKey={1} title={<TabTitleText>Checkbox layout</TabTitleText>} aria-label="Checkbox layout">
          <Stack hasGutter className="pf-v6-u-mt-md">
            {(['cloudwatch', 's3'] as DestinationId[]).map((dest) => (
              <div key={dest}>
                <Checkbox
                  id={`enable-checkbox-${dest}`}
                  label={`Enable ${DESTINATION_LABELS[dest]}`}
                  isChecked={enabledDestinations.includes(dest)}
                  onChange={() => toggleDestination(dest)}
                  aria-label={`Enable ${DESTINATION_LABELS[dest]}`}
                />
                {enabledDestinations.includes(dest) && (
                  <div className="pf-v6-u-pl-2xl pf-v6-u-border-left pf-v6-u-border-color-200 pf-v6-u-ml-sm">
                    <ExpandableSection
                      toggleText="Settings"
                      isExpanded={settingsExpanded[dest]}
                      onToggle={(_e, expanded) =>
                        setSettingsExpanded((prev) => ({ ...prev, [dest]: expanded }))
                      }
                      className="pf-v6-u-mt-sm"
                    >
                      <DestinationSettingsContent
                        dest={dest}
                        {...sharedSettingsProps}
                        variant="flat"
                        contentClassName="pf-v6-u-mt-md pf-v6-u-pl-2xl"
                      />
                    </ExpandableSection>
                  </div>
                )}
              </div>
            ))}
          </Stack>
        </Tab>
      </Tabs>
      {isControlled && (
        <Flex gap={{ default: 'gapSm' }} className="pf-v6-u-mt-lg">
          <Button variant="primary" onClick={() => onSave?.(getCurrentConfig())}>
            Save
          </Button>
          <Button variant="secondary" onClick={onCancel}>
            Cancel
          </Button>
        </Flex>
      )}
    </Stack>
  );
};

const NewPage: React.FunctionComponent = () => {
  const WizardFooter = () => {
    const { activeStep, goToNextStep, goToPrevStep, close } = useWizardContext();
    const totalSteps = 8; // Details, Roles, Machine pools, Networking, Encryption, Cluster updates, Log forwarding, Review
    const isLastStep = activeStep.index === totalSteps - 1;
    const isFirstStep = activeStep.index === 0;

    return (
      <div className="pf-v6-c-wizard__footer">
        <Button
          variant="primary"
          onClick={isLastStep ? () => {} : goToNextStep}
        >
          {isLastStep ? 'Create' : 'Next'}
        </Button>
        {!isFirstStep && (
          <Button variant="secondary" onClick={goToPrevStep}>
            Back
          </Button>
        )}
        <Button variant="link" onClick={close}>
          Cancel
        </Button>
      </div>
    );
  };

  return (
    <PageSection>
      <Title headingLevel="h1" size="lg" className="pf-v6-u-mb-md">
        Create ROSA cluster
      </Title>

      <Wizard title="Create ROSA wizard" height={600} footer={<WizardFooter />}>
        <WizardStep
          id="basic-setup"
          name="Basic set up"
          isExpandable
          steps={[
            <WizardStep key="details" id="details" name="Details">
              <PlaceholderStepContent title="Details" />
            </WizardStep>,
            <WizardStep key="roles-policies" id="roles-policies" name="Roles and policies">
              <PlaceholderStepContent title="Roles and policies" />
            </WizardStep>,
            <WizardStep key="machine-pools" id="machine-pools" name="Machine pools">
              <PlaceholderStepContent title="Machine pools" />
            </WizardStep>,
            <WizardStep key="networking" id="networking" name="Networking">
              <PlaceholderStepContent title="Networking" />
            </WizardStep>,
          ]}
        />

        <WizardStep
          id="additional-setup"
          name="Additional set up"
          isExpandable
          steps={[
            <WizardStep key="encryption" id="encryption" name="Encryption">
              <PlaceholderStepContent title="Encryption" />
            </WizardStep>,
            <WizardStep key="cluster-updates" id="cluster-updates" name="Cluster updates">
              <PlaceholderStepContent title="Cluster updates" />
            </WizardStep>,
            <WizardStep key="log-forwarding" id="log-forwarding" name="Log forwarding">
              <LogForwardingStepContent />
            </WizardStep>,
          ]}
        />

        <WizardStep id="review" name="Review and create" footer={{ nextButtonText: 'Create' }}>
          <Content>
            <p className="pf-v6-u-color-200">Review your configuration and click Create to continue.</p>
          </Content>
        </WizardStep>
      </Wizard>
    </PageSection>
  );
};

export { NewPage, LogForwardingStepContent };
