import * as React from 'react';
import { useParams, Link } from 'react-router-dom';
import {
  PageSection,
  Title,
  Breadcrumb,
  BreadcrumbItem,
  Button,
  Dropdown,
  DropdownItem,
  DropdownList,
  MenuToggle,
  MenuToggleElement,
  ExpandableSection,
  Badge,
  Tabs,
  Tab,
  TabTitleText,
  Card,
  CardTitle,
  CardBody,
  DescriptionList,
  DescriptionListGroup,
  DescriptionListTerm,
  DescriptionListDescription,
  EmptyState,
  EmptyStateBody,
  Grid,
  GridItem,
  Flex,
  FlexItem,
  Stack,
} from '@patternfly/react-core';
import { SyncIcon, PencilAltIcon } from '@patternfly/react-icons';
import {
  LogForwardingStepContent,
  LogForwardingConfig,
  getApplicationName,
  DESTINATION_LABELS,
} from '@app/NewPage/NewPage';

const ClusterDetails: React.FunctionComponent = () => {
  const { clusterId } = useParams<{ clusterId: string }>();
  const clusterName = clusterId ?? 'cluster';
  const [activeTabKey, setActiveTabKey] = React.useState<string | number>(0);
  const [alertsExpanded, setAlertsExpanded] = React.useState(false);
  const [actionsDropdownOpen, setActionsDropdownOpen] = React.useState(false);
  const [logForwardingConfig, setLogForwardingConfig] = React.useState<LogForwardingConfig>({
    enabledDestinations: [],
    selectedApps: { cloudwatch: [], s3: [] },
    cloudwatchRoleArn: '',
    cloudwatchLogGroupName: '',
    s3BucketName: '',
    s3BucketPrefix: '',
  });
  const [isEditingLogForwarding, setIsEditingLogForwarding] = React.useState(false);

  const handleTabSelect = (_e: React.SyntheticEvent<HTMLElement>, tabIndex: string | number) => {
    setActiveTabKey(tabIndex);
  };

  const onActionsToggle = () => {
    setActionsDropdownOpen((prev) => !prev);
  };

  const onActionsSelect = () => {
    setActionsDropdownOpen(false);
  };

  // Sample cluster details matching the console layout
  const clusterDetails = {
    clusterId: 'e7d6ea79-baad-4177-b05c-5c94d6f9874f',
    domainPrefix: clusterName,
    type: 'ROSA',
    controlPlaneType: 'Classic architecture',
    region: 'us-west-2',
    availability: 'Single zone',
    deleteProtection: 'Disabled',
    status: 'Ready - Limited support',
    statusVariant: 'warning' as const,
    totalVcpu: '0 vCPU',
    totalMemory: '0 B',
    infrastructureAccount: '269733383066',
    additionalEncryption: 'Disabled',
  };

  const alertsCount = 2;

  return (
    <>
      <PageSection variant="default">
        <Breadcrumb>
          <BreadcrumbItem to="#">OpenShift</BreadcrumbItem>
          <BreadcrumbItem component={Link} to="/clusters">
            Cluster List
          </BreadcrumbItem>
          <BreadcrumbItem isActive>Cluster details</BreadcrumbItem>
        </Breadcrumb>
        <Flex justifyContent={{ default: 'justifyContentSpaceBetween' }} alignItems={{ default: 'alignItemsFlexStart' }} className="pf-v6-u-mt-md">
          <FlexItem>
            <Title headingLevel="h1" size="2xl">
              Cluster details
            </Title>
          </FlexItem>
          <FlexItem>
            <Flex gap={{ default: 'gapSm' }}>
              <Button variant="primary">Open console</Button>
              <Dropdown
                isOpen={actionsDropdownOpen}
                onSelect={onActionsSelect}
                onOpenChange={(isOpen) => setActionsDropdownOpen(isOpen)}
                toggle={(toggleRef: React.Ref<MenuToggleElement>) => (
                  <MenuToggle ref={toggleRef} onClick={onActionsToggle} isExpanded={actionsDropdownOpen} variant="secondary">
                    Actions
                  </MenuToggle>
                )}
              >
                <DropdownList>
                  <DropdownItem>Edit cluster</DropdownItem>
                  <DropdownItem>Delete cluster</DropdownItem>
                </DropdownList>
              </Dropdown>
              <Button variant="plain" aria-label="Refresh">
                <SyncIcon />
              </Button>
            </Flex>
          </FlexItem>
        </Flex>
        <Flex alignItems={{ default: 'alignItemsCenter' }} gap={{ default: 'gapSm' }} className="pf-v6-u-mt-md">
          <ExpandableSection
            toggleText="Alerts and recommendations"
            onToggle={(_e, expanded) => setAlertsExpanded(expanded)}
            isExpanded={alertsExpanded}
          >
            <div className="pf-v6-u-p-md">
              {alertsExpanded && (
                <p className="pf-v6-u-color-200 pf-v6-u-m-0">
                  Alert and recommendation messages would appear here. This is placeholder content.
                </p>
              )}
            </div>
          </ExpandableSection>
          {alertsCount > 0 && (
            <Badge isRead>{alertsCount}</Badge>
          )}
        </Flex>
      </PageSection>
      <PageSection type="tabs" variant="default">
        <Tabs activeKey={activeTabKey} onSelect={handleTabSelect} aria-label="Cluster details tabs">
          <Tab eventKey={0} title={<TabTitleText>Overview</TabTitleText>} aria-label="Cluster overview">
            <Stack hasGutter className="pf-v6-u-mt-md">
              <Card>
                <CardTitle>Resource usage</CardTitle>
                <CardBody>
                  <EmptyState>
                    <EmptyStateBody>
                      The cluster currently does not have any metrics data. Try again later.
                    </EmptyStateBody>
                  </EmptyState>
                </CardBody>
              </Card>
              <Card>
                <CardTitle>Details</CardTitle>
                <CardBody>
                  <Grid hasGutter md={6}>
                    <GridItem>
                      <DescriptionList isHorizontal columnModifier={{ default: '1Col', md: '2Col' }}>
                        <DescriptionListGroup>
                          <DescriptionListTerm>Cluster ID</DescriptionListTerm>
                          <DescriptionListDescription>{clusterDetails.clusterId}</DescriptionListDescription>
                        </DescriptionListGroup>
                        <DescriptionListGroup>
                          <DescriptionListTerm>Domain prefix</DescriptionListTerm>
                          <DescriptionListDescription>{clusterDetails.domainPrefix}</DescriptionListDescription>
                        </DescriptionListGroup>
                        <DescriptionListGroup>
                          <DescriptionListTerm>Type</DescriptionListTerm>
                          <DescriptionListDescription>{clusterDetails.type}</DescriptionListDescription>
                        </DescriptionListGroup>
                        <DescriptionListGroup>
                          <DescriptionListTerm>Control plane type</DescriptionListTerm>
                          <DescriptionListDescription>{clusterDetails.controlPlaneType}</DescriptionListDescription>
                        </DescriptionListGroup>
                        <DescriptionListGroup>
                          <DescriptionListTerm>Region</DescriptionListTerm>
                          <DescriptionListDescription>{clusterDetails.region}</DescriptionListDescription>
                        </DescriptionListGroup>
                        <DescriptionListGroup>
                          <DescriptionListTerm>Availability</DescriptionListTerm>
                          <DescriptionListDescription>{clusterDetails.availability}</DescriptionListDescription>
                        </DescriptionListGroup>
                      </DescriptionList>
                    </GridItem>
                    <GridItem>
                      <DescriptionList isHorizontal columnModifier={{ default: '1Col', md: '2Col' }}>
                        <DescriptionListGroup>
                          <DescriptionListTerm>Delete Protection</DescriptionListTerm>
                          <DescriptionListDescription>
                            {clusterDetails.deleteProtection}
                            <Button variant="plain" isInline aria-label="Edit delete protection" icon={<PencilAltIcon />} className="pf-v6-u-ml-xs" />
                          </DescriptionListDescription>
                        </DescriptionListGroup>
                        <DescriptionListGroup>
                          <DescriptionListTerm>Status</DescriptionListTerm>
                          <DescriptionListDescription>{clusterDetails.status}</DescriptionListDescription>
                        </DescriptionListGroup>
                        <DescriptionListGroup>
                          <DescriptionListTerm>Total vCPU</DescriptionListTerm>
                          <DescriptionListDescription>{clusterDetails.totalVcpu}</DescriptionListDescription>
                        </DescriptionListGroup>
                        <DescriptionListGroup>
                          <DescriptionListTerm>Total memory</DescriptionListTerm>
                          <DescriptionListDescription>{clusterDetails.totalMemory}</DescriptionListDescription>
                        </DescriptionListGroup>
                        <DescriptionListGroup>
                          <DescriptionListTerm>Infrastructure AWS account</DescriptionListTerm>
                          <DescriptionListDescription>{clusterDetails.infrastructureAccount}</DescriptionListDescription>
                        </DescriptionListGroup>
                        <DescriptionListGroup>
                          <DescriptionListTerm>Additional encryption</DescriptionListTerm>
                          <DescriptionListDescription>{clusterDetails.additionalEncryption}</DescriptionListDescription>
                        </DescriptionListGroup>
                      </DescriptionList>
                    </GridItem>
                  </Grid>
                </CardBody>
              </Card>
            </Stack>
          </Tab>
          <Tab eventKey={1} title={<TabTitleText>Access control</TabTitleText>} aria-label="Access control">
            <Card className="pf-v6-u-mt-md">
              <CardBody>
                <p className="pf-v6-u-color-200">Access control configuration will go here.</p>
              </CardBody>
            </Card>
          </Tab>
          <Tab eventKey={2} title={<TabTitleText>Add-ons</TabTitleText>} aria-label="Add-ons">
            <Card className="pf-v6-u-mt-md">
              <CardBody>
                <p className="pf-v6-u-color-200">Add-ons configuration will go here.</p>
              </CardBody>
            </Card>
          </Tab>
          <Tab eventKey={3} title={<TabTitleText>Cluster history</TabTitleText>} aria-label="Cluster history">
            <Card className="pf-v6-u-mt-md">
              <CardBody>
                <p className="pf-v6-u-color-200">Cluster history will go here.</p>
              </CardBody>
            </Card>
          </Tab>
          <Tab eventKey={4} title={<TabTitleText>Networking</TabTitleText>} aria-label="Networking">
            <Card className="pf-v6-u-mt-md">
              <CardBody>
                <p className="pf-v6-u-color-200">Networking configuration will go here.</p>
              </CardBody>
            </Card>
          </Tab>
          <Tab eventKey={5} title={<TabTitleText>Machine pools</TabTitleText>} aria-label="Machine pools">
            <Card className="pf-v6-u-mt-md">
              <CardBody>
                <p className="pf-v6-u-color-200">Machine pools configuration will go here.</p>
              </CardBody>
            </Card>
          </Tab>
          <Tab eventKey={6} title={<TabTitleText>Log forwarding</TabTitleText>} aria-label="Log forwarding">
            <div className="pf-v6-u-mt-md">
              {!isEditingLogForwarding ? (
                <Card>
                  <CardTitle>Log forwarding configuration</CardTitle>
                  <CardBody>
                    <DescriptionList isHorizontal columnModifier={{ default: '1Col', md: '2Col' }}>
                      <DescriptionListGroup>
                        <DescriptionListTerm>Enabled destinations</DescriptionListTerm>
                        <DescriptionListDescription>
                          {logForwardingConfig.enabledDestinations.length === 0
                            ? 'None'
                            : logForwardingConfig.enabledDestinations
                                .map((d) => DESTINATION_LABELS[d])
                                .join(', ')}
                        </DescriptionListDescription>
                      </DescriptionListGroup>
                      {logForwardingConfig.enabledDestinations.includes('cloudwatch') && (
                        <>
                          <DescriptionListGroup>
                            <DescriptionListTerm>CloudWatch role ARN</DescriptionListTerm>
                            <DescriptionListDescription>
                              {logForwardingConfig.cloudwatchRoleArn || '—'}
                            </DescriptionListDescription>
                          </DescriptionListGroup>
                          <DescriptionListGroup>
                            <DescriptionListTerm>CloudWatch log group name</DescriptionListTerm>
                            <DescriptionListDescription>
                              {logForwardingConfig.cloudwatchLogGroupName || '—'}
                            </DescriptionListDescription>
                          </DescriptionListGroup>
                          <DescriptionListGroup>
                            <DescriptionListTerm>CloudWatch selected applications</DescriptionListTerm>
                            <DescriptionListDescription>
                              {(logForwardingConfig.selectedApps.cloudwatch?.length ?? 0) === 0
                                ? 'None'
                                : (logForwardingConfig.selectedApps.cloudwatch ?? [])
                                    .map(getApplicationName)
                                    .join(', ')}
                            </DescriptionListDescription>
                          </DescriptionListGroup>
                        </>
                      )}
                      {logForwardingConfig.enabledDestinations.includes('s3') && (
                        <>
                          <DescriptionListGroup>
                            <DescriptionListTerm>S3 bucket name</DescriptionListTerm>
                            <DescriptionListDescription>
                              {logForwardingConfig.s3BucketName || '—'}
                            </DescriptionListDescription>
                          </DescriptionListGroup>
                          <DescriptionListGroup>
                            <DescriptionListTerm>S3 bucket prefix</DescriptionListTerm>
                            <DescriptionListDescription>
                              {logForwardingConfig.s3BucketPrefix || '—'}
                            </DescriptionListDescription>
                          </DescriptionListGroup>
                          <DescriptionListGroup>
                            <DescriptionListTerm>S3 selected applications</DescriptionListTerm>
                            <DescriptionListDescription>
                              {(logForwardingConfig.selectedApps.s3?.length ?? 0) === 0
                                ? 'None'
                                : (logForwardingConfig.selectedApps.s3 ?? []).map(getApplicationName).join(', ')}
                            </DescriptionListDescription>
                          </DescriptionListGroup>
                        </>
                      )}
                    </DescriptionList>
                    <Button variant="primary" className="pf-v6-u-mt-md" onClick={() => setIsEditingLogForwarding(true)}>
                      Edit
                    </Button>
                  </CardBody>
                </Card>
              ) : (
                <LogForwardingStepContent
                  initialConfig={logForwardingConfig}
                  onSave={(config) => {
                    setLogForwardingConfig(config);
                    setIsEditingLogForwarding(false);
                  }}
                  onCancel={() => setIsEditingLogForwarding(false)}
                />
              )}
            </div>
          </Tab>
          <Tab eventKey={7} title={<TabTitleText>Support</TabTitleText>} aria-label="Support">
            <Card className="pf-v6-u-mt-md">
              <CardBody>
                <p className="pf-v6-u-color-200">Support information will go here.</p>
              </CardBody>
            </Card>
          </Tab>
        </Tabs>
      </PageSection>
    </>
  );
};

export { ClusterDetails };
